SET statement_timeout = '15s';
SET lock_timeout = '5s';
DO $$
BEGIN
 IF current_database() <> 'postgres' THEN RAISE EXCEPTION 'wrong control database'; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_database WHERE datname='epheros' AND oid=406059 AND pg_get_userbyid(datdba)='epheros_owner') THEN RAISE EXCEPTION 'target identity changed'; END IF;
 IF EXISTS (SELECT 1 FROM pg_stat_activity WHERE datname='epheros') THEN RAISE EXCEPTION 'target acquired active sessions'; END IF;
 IF EXISTS (SELECT 1 FROM pg_prepared_xacts WHERE database='epheros') OR EXISTS (SELECT 1 FROM pg_replication_slots WHERE database='epheros') THEN RAISE EXCEPTION 'target has prepared work or replication'; END IF;
END $$;
DROP DATABASE "epheros";
SELECT json_build_object('epheros_absent',NOT EXISTS (SELECT 1 FROM pg_database WHERE datname='epheros'),'databases',(SELECT json_agg(row_to_json(x)) FROM (SELECT oid,datname,pg_get_userbyid(datdba) AS owner,datallowconn AS allow_connections FROM pg_database ORDER BY datname) x));
